      <Dialog open={icsImportOpen} onOpenChange={(open) => { if (!open) { setIcsImportOpen(false); setIcsImportEvents([]); } }}>
        <DialogContent className="max-w-[640px] max-h-[85vh] bg-gradient-to-br from-gray-900/98 via-black/95 to-gray-800/98 text-white p-0 overflow-hidden" style={{ fontFamily: "Avenir, 'Avenir Next', -apple-system, BlinkMacSystemFont, sans-serif" }}>
          <DialogHeader className="px-5 py-3 border-b border-white/15" style={{ background: 'rgba(139, 92, 246, 0.15)' }}>
            <DialogTitle className="text-sm font-normal text-white flex items-center gap-2">
              <Upload className="h-4 w-4 text-violet-400" />
              Import ICS Events ({icsImportEvents.filter(e => e.selected).length} of {icsImportEvents.length} selected)
            </DialogTitle>
          </DialogHeader>
          <div className="overflow-y-auto px-4 py-3 flex-1" style={{ maxHeight: 'calc(85vh - 140px)', scrollbarWidth: 'thin' }}>
            <div className="flex items-center justify-between mb-3">
              <button
                className="text-[10px] text-violet-400 hover:text-violet-300 transition-colors"
                onClick={() => {
                  const allSelected = icsImportEvents.every(e => e.selected);
                  setIcsImportEvents(prev => prev.map(e => ({ ...e, selected: !allSelected })));
                }}
                data-testid="button-ics-toggle-all"
              >
                {icsImportEvents.every(e => e.selected) ? 'Deselect All' : 'Select All'}
              </button>
            </div>
            <div className="flex flex-col gap-1.5">
              {icsImportEvents.map((ev, idx) => (
                <div
                  key={idx}
                  className={`rounded-lg border px-3 py-2 transition-all cursor-pointer ${ev.selected ? 'bg-white/10 border-violet-400/40' : 'bg-white/3 border-white/10 opacity-50'}`}
                  onClick={() => setIcsImportEvents(prev => prev.map((e, i) => i === idx ? { ...e, selected: !e.selected } : e))}
                  data-testid={`ics-event-${idx}`}
                >
                  <div className="flex items-start gap-2">
                    <div className="mt-0.5">
                      <div style={{ width: '14px', height: '14px', border: '1.5px solid rgba(255,255,255,0.5)', borderRadius: '3px', backgroundColor: ev.selected ? '#8b5cf6' : 'transparent', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        {ev.selected && <Check className="h-2.5 w-2.5 text-white" strokeWidth={3} />}
                      </div>
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-[11px] font-medium text-white truncate">{ev.title}</div>
                      <div className="flex items-center gap-2 mt-0.5">
                        {ev.startDate && (
                          <span className="text-[9px] text-white/50">
                            {format(new Date(ev.startDate), 'MMM d, yyyy')}
                            {!ev.allDay && ` ${format(new Date(ev.startDate), 'h:mm a')}`}
                            {ev.endDate && ev.endDate !== ev.startDate && !ev.allDay && ` — ${format(new Date(ev.endDate), 'h:mm a')}`}
                          </span>
                        )}
                        {ev.location && <span className="text-[9px] text-white/40 truncate max-w-[150px]">{ev.location}</span>}
                      </div>
                      {ev.description && <div className="text-[8px] text-white/35 mt-0.5 line-clamp-1">{ev.description.slice(0, 100)}</div>}
                    </div>
                    <div className="flex flex-col gap-1 flex-shrink-0" onClick={(e) => e.stopPropagation()}>
                      <select
                        className="text-[9px] bg-white/10 border border-white/15 rounded px-1 py-0.5 text-white w-[85px]"
                        value={ev.type}
                        onChange={(e) => { const v = e.target.value; startTransition(() => setIcsImportEvents(prev => prev.map((item, i) => i === idx ? { ...item, type: v } : item))); }}
                        data-testid={`ics-event-type-${idx}`}
                      >
                        {TASK_TYPES.map(t => <option key={t} value={t}>{t.charAt(0).toUpperCase() + t.slice(1)}</option>)}
                      </select>
                      <select
                        className="text-[9px] bg-white/10 border border-white/15 rounded px-1 py-0.5 text-white w-[85px]"
                        value={ev.courseName}
                        onChange={(e) => { const v = e.target.value; startTransition(() => setIcsImportEvents(prev => prev.map((item, i) => i === idx ? { ...item, courseName: v } : item))); }}
                        data-testid={`ics-event-course-${idx}`}
                      >
                        <option value="">No course</option>
                        {COURSES.map(c => <option key={c.code} value={`${c.code} - ${c.name}`}>{c.code}</option>)}
                      </select>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div className="px-4 py-3 border-t border-white/15 flex items-center justify-between">
            <span className="text-[10px] text-white/40">{icsImportEvents.filter(e => e.selected).length} event{icsImportEvents.filter(e => e.selected).length !== 1 ? 's' : ''} will be imported as tasks</span>
            <div className="flex gap-2">
              <Button
                variant="outline"
                className="border !border-white/30 text-white/70 hover:text-white hover:!border-white/50 hover:bg-transparent h-8 px-4"
                style={{ fontSize: '11px' }}
                onClick={() => { setIcsImportOpen(false); setIcsImportEvents([]); }}
                data-testid="button-ics-cancel"
              >
                Cancel
              </Button>
              <Button
                variant="outline"
                className="border !border-violet-400/50 text-white hover:!border-violet-400 hover:bg-violet-500/20 h-8 px-4"
                style={{ fontSize: '11px', boxShadow: '0 0 8px rgba(139,92,246,0.3)' }}
                onClick={handleIcsImportConfirm}
                disabled={icsImporting || icsImportEvents.filter(e => e.selected).length === 0}
                data-testid="button-ics-import-confirm"
              >
                {icsImporting ? 'Importing...' : `Import ${icsImportEvents.filter(e => e.selected).length} Event${icsImportEvents.filter(e => e.selected).length !== 1 ? 's' : ''}`}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {selectedCertCourse && (() => {
        const info = buildCourseInfoForCert();
        if (!info) return null;
        const ck = selectedCertCourse.certKey;
        const certName = (() => {
          const cc = selectedCertCourse.courseCode.replace(/\s/g, '').toUpperCase();
          const ccBase = cc.replace(/^C(?=[A-Z]{2,})/, '');
          let bestLevel = 0;
          for (const level of ['L1', 'L2', 'L3'] as const) {
            const lvl = level === 'L3' ? 3 : level === 'L2' ? 2 : 1;
            for (const section of certSections[level]) {
              for (const member of section.members) {
                const memberBase = member.replace(/^L[123]_/, '').toUpperCase();
                if (memberBase === cc || memberBase === ccBase || member === ck) {
                  if (lvl > bestLevel) bestLevel = lvl;
                }
              }
            }
          }
          if (bestLevel === 3) return 'Certificate 3';
          if (bestLevel === 2) return 'Certificate 2';
          if (bestLevel === 1) return 'Certificate 1';
          if (ck.startsWith('L3_')) return 'Certificate 3';
          if (ck.startsWith('L2_')) return 'Certificate 2';
          return 'Certificate 1';
        })();
        return (
          <CourseDetailDialog
            courseInfo={info}
            certificateName={certName}
            onClose={() => {
              startTransition(() => setSelectedCertCourse(null));
              if (isSchoolCoursesDialogOpen) {
                // School Courses dialog is still open underneath, just go back to it
              } else if (openedCourseFromDegreeTracking) {
                setOpenedCourseFromDegreeTracking(false);
                startTransition(() => setIsSettingsPanelOpen(true));
              }
            }}
            onSaveCourseInfo={(updates) => {
              const courseCode = selectedCertCourse!.courseCode;
              const certKey = selectedCertCourse!.certKey;
              const updatedCourses = [...coursesData.courses];
              const matchIdx = updatedCourses.findIndex(c => {
                const cCode = c.name.split(' - ')[0]?.trim().replace(/\s/g, '');
                return cCode === courseCode.replace(/\s/g, '');
              });
              if (matchIdx >= 0) {
                updatedCourses[matchIdx] = {
                  ...updatedCourses[matchIdx],
                  professor: updates.professor || updatedCourses[matchIdx].professor,
                  professorEmail: updates.professorEmail || updatedCourses[matchIdx].professorEmail,
                  ...(updates.color ? { color: updates.color } : {}),
                  ...(updates.colorEnd ? { colorEnd: updates.colorEnd } : {}),
                };
                saveCourses({ courses: updatedCourses });
              }
              const computeSemesterDates = (term: string, yr: string) => {
                const y = parseInt(yr);
                if (!y) return { startDate: '', endDate: '', semesterType: '', springSummerTerm: '' };
                switch (term) {
                  case 'fall': return { startDate: `${y}-09-08`, endDate: `${y}-12-07`, semesterType: 'fall', springSummerTerm: '' };
                  case 'winter': return { startDate: `${y}-01-13`, endDate: `${y}-04-17`, semesterType: 'winter', springSummerTerm: '' };
                  case 'spring_summer_full': return { startDate: `${y}-05-05`, endDate: `${y}-08-04`, semesterType: 'spring_summer', springSummerTerm: 'full' };
                  case 'spring_summer_first': return { startDate: `${y}-05-05`, endDate: `${y}-06-20`, semesterType: 'spring_summer', springSummerTerm: 'first_half' };
                  case 'spring_summer_second': return { startDate: `${y}-06-23`, endDate: `${y}-08-04`, semesterType: 'spring_summer', springSummerTerm: 'second_half' };
                  default: return { startDate: '', endDate: '', semesterType: '', springSummerTerm: '' };
                }
              };
              const currentSemSettings = allSemesterSettingsRef.current;
              if (currentSemSettings) {
                const cc = courseCode.replace(/\s/g, '');
                let found = false;
                for (const sem of currentSemSettings) {
                  for (let i = 1; i <= 3; i++) {
                    const semCode = ((sem as any)[`course${i}Code`] || '').replace(/\s/g, '');
                    if (semCode === cc) {
                      found = true;
                      const prefix = `course${i}`;
                      const payload: Record<string, any> = {};
                      if (updates.deliveryMode !== undefined) payload[`${prefix}DeliveryMode`] = updates.deliveryMode;
                      if (updates.classDay !== undefined) payload[`${prefix}ClassDay`] = updates.classDay;
                      if (updates.classDay2 !== undefined) payload[`${prefix}ClassDay2`] = updates.classDay2;
                      if (updates.classTime !== undefined) payload[`${prefix}ClassTime`] = updates.classTime;
                      if (updates.classEndTime !== undefined) payload[`${prefix}ClassEndTime`] = updates.classEndTime;
                      if (updates.zoomLink !== undefined) payload[`${prefix}ZoomLink`] = updates.zoomLink;
                      if (updates.professor !== undefined) payload[`${prefix}Professor`] = updates.professor;
                      if (updates.professorEmail !== undefined) payload[`${prefix}ProfessorEmail`] = updates.professorEmail;
                      if (updates.color !== undefined) payload[`${prefix}Color`] = updates.color;
                      if (updates.colorEnd !== undefined) payload[`${prefix}ColorEnd`] = updates.colorEnd;
                      if (updates.semesterTerm && updates.year) {
                        const dates = computeSemesterDates(updates.semesterTerm, updates.year);
                        if (dates.startDate) {
                          payload[`${prefix}StartDate`] = new Date(dates.startDate).toISOString();
                          payload[`${prefix}EndDate`] = new Date(dates.endDate).toISOString();
                          if (dates.springSummerTerm) payload[`${prefix}SpringSummerTerm`] = dates.springSummerTerm;
                        }
                      }
                      if (Object.keys(payload).length > 0) {
                        queryClient.setQueryData(["/api/semesters"], (old: any[] | undefined) => {
                          if (!old) return old;
                          return old.map((s: any) => s.id === sem.id ? { ...s, ...payload } : s);
                        });
                        if (updates.deliveryMode !== undefined) {
                          queryClient.setQueryData(["/api/semester"], (old: any) => {
                            if (!old || old.id !== sem.id) return old;
                            return { ...old, ...payload };
                          });
                        }
                        apiRequest("PATCH", `/api/semesters/${sem.id}`, payload).then(() => {
                          queryClient.invalidateQueries({ queryKey: ["/api/semesters"] });
                          queryClient.invalidateQueries({ queryKey: ["/api/semester"] });
                          if (updates.classDay && updates.classTime && updates.classEndTime && updates.semesterTerm && updates.year) {
                            const dates = computeSemesterDates(updates.semesterTerm, updates.year);
                            if (dates.startDate) {
                              const courseName = updatedCourses[matchIdx >= 0 ? matchIdx : 0]?.name || `${courseCode}`;
                              const [sY, sM, sD] = dates.startDate.split('-').map(Number);
                              const startD = new Date(sY, sM - 1, sD);
                              const [eY, eM, eD] = dates.endDate.split('-').map(Number);
                              const endD = new Date(eY, eM - 1, eD);
                              const dayMap: Record<string, number> = { sunday: 0, monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6 };
                              const classDays = [updates.classDay, updates.classDay2].filter(Boolean).map(d => dayMap[d!] ?? -1).filter(d => d >= 0);
                              const existingTasks: any[] = queryClient.getQueryData(["/api/tasks"]) || [];
                              const existingClassTasks = existingTasks.filter((t: any) =>
                                t.type === 'class' && (t.courseName || '').includes(courseCode)
                              );
                              const effectiveDM = updates.deliveryMode || (sem as any)[`${prefix}DeliveryMode`] || '';
                              const dmLabel = effectiveDM === 'virtual' ? 'Online' : effectiveDM === 'online' ? 'Online' : effectiveDM === 'in-person' ? 'In-Person' : '';
                              const cNameShort = courseName.split(' - ').slice(1).join(' - ') || courseName;
                              const classTitle = dmLabel ? `${dmLabel} ${cNameShort} Class` : `${cNameShort} Class`;
                              const buildClassTasks = () => {
                                const tasksToCreate: Array<{ title: string; type: string; dueDate: string; courseName: string; eventStartTime: string; eventEndTime: string; priority: string; weekNumber: number }> = [];
                                const current = new Date(startD);
                                while (current <= endD) {
                                  if (classDays.includes(current.getDay())) {
                                    const diffWeeks = Math.floor((current.getTime() - startD.getTime()) / (7*24*60*60*1000));
                                    const weekNum = Math.min(Math.max(diffWeeks + 1, 1), 13);
                                    tasksToCreate.push({
                                      title: classTitle,
                                      type: 'class',
                                      dueDate: `${current.getFullYear()}-${(current.getMonth()+1).toString().padStart(2,'0')}-${current.getDate().toString().padStart(2,'0')}T12:00:00`,
                                      courseName,
                                      eventStartTime: updates.classTime!,
                                      eventEndTime: updates.classEndTime!,
                                      priority: 'medium',
                                      weekNumber: weekNum,
                                    });
                                  }
                                  current.setDate(current.getDate() + 1);
                                }
                                return tasksToCreate;
                              };
                              if (existingClassTasks.length > 0) {
                                Promise.all(existingClassTasks.map((t: any) => apiRequest("DELETE", `/api/tasks/${t.id}`))).then(() => {
                                  const tasksToCreate = buildClassTasks();
                                  if (tasksToCreate.length > 0) {
                                    Promise.all(tasksToCreate.map(t => apiRequest("POST", "/api/tasks", t))).then(() => {
                                      queryClient.invalidateQueries({ queryKey: ["/api/tasks"] });
                                      toast({ title: "Class tasks updated", description: `${tasksToCreate.length} class sessions refreshed on calendar.` });
                                    });
                                  }
                                });
                              } else {
                                const tasksToCreate = buildClassTasks();
                                if (tasksToCreate.length > 0) {
                                  Promise.all(tasksToCreate.map(t => apiRequest("POST", "/api/tasks", t))).then(() => {
                                    queryClient.invalidateQueries({ queryKey: ["/api/tasks"] });
                                    toast({ title: "Class tasks created", description: `${tasksToCreate.length} class sessions added to calendar.` });
                                  });
                                }
                              }
                            }
                          }
                        });
                      }
                      break;
                    }
                  }
                }
              }
              const certData = localStorage.getItem('certCourseData');
              const savedData = certData ? JSON.parse(certData) : {};
              savedData[certKey] = { ...savedData[certKey], ...updates };
              const cc = courseCode.replace(/\s/g, '');
              if (certKey !== cc && updates.deliveryMode) {
                savedData[cc] = { ...(savedData[cc] || {}), deliveryMode: updates.deliveryMode };
              }
              localStorage.setItem('certCourseData', JSON.stringify(savedData));
              saveDegreeToServer('certCourseData', savedData);
              setDeliveryModeVersion(v => v + 1);
            }}
            onGradeCalculated={(grade, percent) => {
              const certKey = selectedCertCourse!.certKey;
              const courseCode = selectedCertCourse!.courseCode;
              updateGrade(certKey, grade);
              updatePercent(certKey, percent);
              const codeNorm = courseCode.replace(/\s/g,'').toUpperCase();
              for (const [ck, info] of Object.entries(certCourseMap)) {
                if (ck === certKey) continue;
                if (shouldStrikethrough(ck)) continue;
                const mapCode = info.code.replace(/\s/g,'').toUpperCase();
                if (mapCode === codeNorm || codeNorm.endsWith(mapCode) || mapCode.endsWith(codeNorm.replace(/^C/,''))) {
                  updateGrade(ck, grade);
                  updatePercent(ck, percent);
                }
              }
              const electiveSlots = ['LIBERAL','OPEN1','OPEN2','L2_LIBERAL','L2_OPEN1','L2_OPEN2','L3_OPEN1','L3_OPEN2','L3_OPEN3','L3_OPEN4','L3_OPEN5','L3_OPEN6','L3_OPEN7'];
              for (const slot of electiveSlots) {
                if (slot === certKey) continue;
                const elVal = openElectives[slot];
                if (elVal && elVal.replace(/\s/g,'').toUpperCase().startsWith(codeNorm)) {
                  updateGrade(slot, grade);
                  updatePercent(slot, percent);
                }
              }
            }}
            onDeleteCourse={() => {
              const courseCode = selectedCertCourse!.courseCode;
              const updatedCourses = coursesData.courses.filter(c => {
                const cCode = c.name.split(' - ')[0]?.trim().replace(/\s/g, '');
                return cCode !== courseCode.replace(/\s/g, '');
              });
              saveCourses({ courses: updatedCourses });
              startTransition(() => setSelectedCertCourse(null));
              toast({ title: "Course deleted", description: `${courseCode} has been removed.` });
            }}
            onOpenEditTask={(task) => {
              startTransition(() => setSelectedCertCourse(null));
              setTimeout(() => {
                setEditingTask(task);
              }, 150);
            }}
            semesterStart={semStart || new Date()}
            readingWeekStart={readingWeekStart}
            onPushUndo={(action) => pushUndo(action as UndoAction)}
          />
        );
      })()}

      
      
      {pendingSleepTask && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/50" onClick={() => setPendingSleepTask(null)} data-testid="sleep-confirm-overlay">
          <div 
            className="rounded-xl w-[400px] overflow-hidden flex flex-col text-white shadow-2xl"
            style={{
              background: `linear-gradient(180deg, ${colorSettings.mainBackground} 0%, color-mix(in srgb, ${colorSettings.mainBackgroundGradientEnd} 70%, black) 100%)`,
              border: '1px solid rgba(255, 255, 255, 0.2)',
              fontFamily: "Avenir, 'Avenir Next', -apple-system, BlinkMacSystemFont, sans-serif"
            }}
            onClick={(e) => e.stopPropagation()}
            data-testid="sleep-confirm-dialog"
          >
            <div className="flex items-center gap-3 px-5 py-4 bg-black/30 border-b border-white/20">
              <MoonIcon className="h-5 w-5 text-purple-300" />
              <h3 className="text-sm font-semibold">Sleep Hours</h3>
            </div>
            <div className="px-5 py-5">
              <p className="text-sm text-white/90 leading-relaxed">
                This time slot falls during scheduled sleep hours. Are you sure you want to add a task here?
              </p>
            </div>
            <div className="flex items-center justify-end gap-3 px-5 py-4 border-t border-white/20">
              <Button
                variant="outline"
                className="border !border-white/50 text-white hover:text-white hover:!border-white hover:bg-white/10"
                onClick={() => setPendingSleepTask(null)}
                data-testid="sleep-confirm-cancel"
              >
                Cancel
              </Button>
              <Button
                className="bg-white/20 text-white hover:bg-white/30 border border-white/30"
                onClick={() => {
                  const { day, hour, minutes } = pendingSleepTask;
                  const dueDate = new Date(day);
                  dueDate.setHours(hour, minutes, 0, 0);
                  setSelectedDate(dueDate);
                  setNewTaskType("other");
                  setInitialStartTime(`${hour.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`);
                  setInitialEndTime(`${(hour + 1).toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`);
                  bringFlyoutToFront('addTask');
                  setIsAddDialogOpen(true);
                  setPendingSleepTask(null);
                }}
                data-testid="sleep-confirm-proceed"
              >
                Add Task Anyway
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Copyright - Right side of page, right-aligned with homework box */}
      {!isTodoFlyoutOpen && (
        <div 
          className="fixed text-white/60 text-[11px] font-medium z-[70] pointer-events-none"
          style={{ bottom: '40px', right: `${calendarRight - calendarReduction + 3 + 7 - 6 + 2 + 4 + 2 - 17 - 7 - 2 + 3 + 2 + 8 + 2 + 4}px`, transformOrigin: 'right bottom' }}
        >
          © 2026
        </div>
      )}
      
      {/* Navigation Arrows with week dates + Month toggle - bottom aligned */}
      {!isSettingsPanelOpen && !isSchoolCoursesDialogOpen && (
      <div className="fixed z-50 flex items-end justify-end gap-2" data-tpo data-tpo-opacity="1" style={{ top: `${calendarTop - 26}px`, right: '14px', opacity: isTopPillOpen ? 0 : 1, transition: isTopPillOpen ? 'opacity 0.3s ease-in-out' : 'opacity 0.1s ease-in-out', pointerEvents: isTopPillOpen ? 'none' : 'auto' }}>
        <div className="flex items-center gap-1">
          <span className="text-[10.5px] text-white font-medium leading-tight whitespace-nowrap" style={{ marginRight: '4px' }}>{selectedWeek >= FIRST_WEEK && selectedWeek <= LAST_WEEK ? `Week ${selectedWeek}` : ''}{(() => { const cw = semesterSettings?.semesterStartDate ? getWeekNumber(new Date(), new Date(semesterSettings.semesterStartDate), semesterSettings.readingWeekStart) : null; return cw === selectedWeek && selectedWeek >= FIRST_WEEK && selectedWeek <= LAST_WEEK ? <span className="text-[10px] text-white/60 font-normal ml-1">(current)</span> : null; })()}</span>
          <div 
            className="cursor-pointer hover:bg-white/20 rounded flex items-center justify-center"
            style={{ marginLeft: '2px', padding: '4px 6px', minWidth: '28px', minHeight: '28px' }}
            onClick={() => { const newWeek = selectedWeek - 1; startTransition(() => setSelectedWeek(newWeek)); if (newWeek >= FIRST_WEEK && newWeek <= LAST_WEEK) scrollHomeworkToWeek(newWeek); }}
            data-testid="button-pill-prev-week"
            data-date-nav
          >
            <ChevronLeft style={{ width: '20px', height: '20px' }} className="text-white" strokeWidth={2.5} />
          </div>
          <span className="text-[12px] text-white whitespace-nowrap font-medium leading-tight" data-testid="text-week-dates">
            {format(weekStartDate, 'EEE, MMMM d')} – {format(weekEndDate, 'EEE, MMMM d')}
          </span>
          <div 
            className="cursor-pointer hover:bg-white/20 rounded flex items-center justify-center"
            style={{ marginLeft: '2px', padding: '4px 6px', minWidth: '28px', minHeight: '28px' }}
            onClick={() => { const newWeek = selectedWeek + 1; startTransition(() => setSelectedWeek(newWeek)); if (newWeek >= FIRST_WEEK && newWeek <= LAST_WEEK) scrollHomeworkToWeek(newWeek); }}
            data-testid="button-pill-next-week"
            data-date-nav
          >
            <ChevronRight style={{ width: '20px', height: '20px' }} className="text-white" strokeWidth={2.5} />
          </div>
        </div>
      </div>
      )}
      
      {/* Voice Input Floating Button */}
      <div className="fixed z-[9999]" style={{ bottom: '43px', left: '5px' }}>
        <button
          onClick={() => isVoiceListening ? stopVoiceInput() : startVoiceInput()}
          className={`flex items-center gap-2 rounded-full shadow-lg transition-all duration-300 ${isVoiceListening ? 'bg-red-500 hover:bg-red-600 pr-4' : 'bg-white/15 hover:bg-white/25 backdrop-blur-md border border-white/20'}`}
          style={{ padding: isVoiceListening ? '10px 16px 10px 12px' : '9px', minWidth: isVoiceListening ? '120px' : '36px' }}
          data-testid="button-voice-input"
        >
          {isVoiceListening ? (
            <>
              <MicOff className="h-4 w-4 text-white shrink-0" />
              <div className="flex flex-col items-start min-w-0">
                <span className="text-[10px] text-white font-medium">Listening...</span>
                {voiceTranscript && <span className="text-[9px] text-white/70 truncate max-w-[160px]">{voiceTranscript}</span>}
              </div>
              <span className="w-2 h-2 rounded-full bg-white animate-pulse shrink-0" />
            </>
          ) : (
            <Mic className="text-white" style={{ height: '18px', width: '18px' }} />
          )}
        </button>
      </div>

      {/* News Ticker */}
      <NewsTickerPortal headlines={[
        ...weatherAlerts.map(a => ({ title: `⚠️ ${a.title}`, source: '_ALERT_', link: '' })),
        ...(weatherData ? (() => {
          const WMO_DESC: Record<number, string> = { 0:'Clear',1:'Mainly Clear',2:'Partly Cloudy',3:'Overcast',45:'Fog',48:'Rime Fog',51:'Light Drizzle',53:'Drizzle',55:'Heavy Drizzle',61:'Light Rain',63:'Rain',65:'Heavy Rain',66:'Freezing Rain',67:'Heavy Freezing Rain',71:'Light Snow',73:'Snow',75:'Heavy Snow',77:'Snow Grains',80:'Light Showers',81:'Showers',82:'Heavy Showers',85:'Light Snow Showers',86:'Heavy Snow Showers',95:'Thunderstorm',96:'Thunderstorm w/ Hail',99:'Severe Thunderstorm' };
          const desc = WMO_DESC[weatherData.code] || 'Mixed';
          const items: { title: string; source: string; link: string }[] = [];
          items.push({ title: `<img src="${cnTowerPath}" style="height:34px;width:auto;display:inline-block;vertical-align:middle;margin-right:9px" />Toronto Forecast: ${Math.round(weatherData.temp)}°C — ${desc}  |  Wind: ${Math.round(weatherData.windSpeed)} km/h`, source: '_FORECAST_NOSEP_', link: '' });
          if (weatherData.daily && weatherData.daily.length >= 3) {
            const dayNames = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
            const forecastParts = weatherData.daily.slice(0, 3).map(d => {
              const dt = new Date(d.date + 'T12:00:00');
              const dayName = dayNames[dt.getDay()];
              return `${dayName}: ${Math.round(d.high)}°/${Math.round(d.low)}°`;
            });
            items.push({ title: `<img src="${forecastIconPath}" style="height:20px;width:auto;display:inline-block;vertical-align:middle;margin-left:3px;margin-right:9px;position:relative;top:-2px" />3-Day Forecast: ${forecastParts.join('  •  ')}`, source: '_FORECAST_', link: '' });
            const briefParts: string[] = [];
            const todayD = weatherData.daily[0];
            const tomorrowD = weatherData.daily[1];
            const day3D = weatherData.daily[2];
            const wmoShort = (c: number) => ({ 0:'clear',1:'mostly clear',2:'partly cloudy',3:'overcast',45:'foggy',48:'foggy',51:'light drizzle',53:'drizzle',55:'heavy drizzle',61:'light rain',63:'rain',65:'heavy rain',66:'freezing rain',67:'heavy freezing rain',71:'light snow',73:'snow',75:'heavy snow',77:'snow grains',80:'light showers',81:'showers',82:'heavy showers',85:'light snow showers',86:'heavy snow showers',95:'thunderstorms',96:'thunderstorms with hail',99:'severe thunderstorms' }[c] || 'mixed conditions');
            const todayDesc = wmoShort(todayD.weatherCode || weatherData.code);
            briefParts.push(`Currently ${Math.round(weatherData.temp)}° and ${todayDesc}. Today's high ${Math.round(todayD.high)}°, low ${Math.round(todayD.low)}°.`);
            if (tomorrowD) {
              const tmrDesc = wmoShort(tomorrowD.weatherCode || 0);
              const tmrName = dayNames[new Date(tomorrowD.date + 'T12:00:00').getDay()];
              briefParts.push(`${tmrName}: ${tmrDesc}, ${Math.round(tomorrowD.high)}°/${Math.round(tomorrowD.low)}°.`);
            }
            if (day3D) {
              const d3Desc = wmoShort(day3D.weatherCode || 0);
              const d3Name = dayNames[new Date(day3D.date + 'T12:00:00').getDay()];
              briefParts.push(`${d3Name}: ${d3Desc}, ${Math.round(day3D.high)}°/${Math.round(day3D.low)}°.`);
            }
            items.push({ title: `<img src="${newspaperIconPath}" style="height:22px;width:auto;display:inline-block;vertical-align:middle;margin-right:9px;position:relative;top:-2px" />Forecast Brief: ${briefParts.join('  ')}`, source: '_FORECAST_NOSEP_', link: '' });
          }
          return items;
        })() : []),
        ...(pollenData ? [{ title: `<span style="margin-left:17px;font-size:17px;margin-right:4px;vertical-align:middle">🌿</span>Pollen: ${pollenData.overall.level} (Tree: ${pollenData.tree.level}, Grass: ${pollenData.grass.level}, Weed: ${pollenData.weed.level})  |  AQI: ${pollenData.aqi} (${pollenData.aqi <= 50 ? 'Good' : pollenData.aqi <= 100 ? 'Moderate' : pollenData.aqi <= 150 ? 'Unhealthy for Sensitive' : pollenData.aqi <= 200 ? 'Unhealthy' : pollenData.aqi <= 300 ? 'Very Unhealthy' : 'Hazardous'})`, source: '_FORECAST_NOSEP_', link: '' }] : []),
        ...(() => {
          const US_SOURCES = ['CNN', 'Politico', 'Raw Story', 'MSNBC', 'ABC News', 'Fox News'];
          const ca = newsHeadlines.filter(h => !US_SOURCES.includes(h.source) && h.source !== 'BBC');
          const us = newsHeadlines.filter(h => US_SOURCES.includes(h.source));
          const bbc = newsHeadlines.filter(h => h.source === 'BBC');
          const interleaved: typeof newsHeadlines = [];
          const max = Math.max(ca.length, us.length, bbc.length);
          for (let i = 0; i < max; i++) {
            if (i < ca.length) interleaved.push(ca[i]);
            if (i < us.length) interleaved.push(us[i]);
            if (i < bbc.length) interleaved.push(bbc[i]);
          }
          return interleaved;
        })(),
      ]} />

